// Demonstrating key importance
function TodoList({ todos }) {
  return (
    <ul>
      {todos.map(todo => (
        // Without key: React can't distinguish items on reorder
        // With stable key: React tracks each item by ID
        <li key={todo.id}>
          <TodoItem todo={todo} />
        </li>
      ))}
    </ul>
  );
}

// Demonstrating element type heuristic
function ConditionalComponent({ isLoggedIn }) {
  // React unmounts/remounts completely on type change
  // The input state is NOT preserved when switching
  if (isLoggedIn) {
    return <UserDashboard />; // completely different tree
  }
  return <GuestView />;
}

// Correct: hooks always called in the same order
function Profile({ userId }) {
  const [user, setUser] = useState(null);     // slot 1: always
  const [loading, setLoading] = useState(true); // slot 2: always

  useEffect(() => {
    // slot 3: always — conditional LOGIC inside is fine
    if (userId) {
      fetchUser(userId).then(setUser);
    }
  }, [userId]);

  // Conditional rendering, not conditional hooks
  if (loading) return <Spinner />;
  return <UserCard user={user} />;
}

// useReducer for a multi-step form
const initialState = { step: 1, name: '', email: '', plan: null };

function formReducer(state, action) {
  switch (action.type) {
    case 'NEXT_STEP': return { ...state, step: state.step + 1 };
    case 'SET_NAME': return { ...state, name: action.payload };
    case 'SET_EMAIL': return { ...state, email: action.payload };
    case 'SELECT_PLAN': return { ...state, plan: action.payload, step: 3 };
    default: return state;
  }
}

function SignupForm() {
  const [state, dispatch] = useReducer(formReducer, initialState);

  return (
    <div>
      {state.step === 1 && <NameStep dispatch={dispatch} name={state.name} />}
      {state.step === 2 && <PlanStep dispatch={dispatch} />}
    </div>
  );
}
